-- ILMORA 1.0 starter. Run once in a NEW Supabase project. All live answers are private.
begin;
create schema if not exists ilmora_private;
revoke all on schema ilmora_private from public, anon, authenticated;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 80),nickname text not null default '' check(length(nickname)<=40),role text not null default 'student' check(role in ('student','teacher','admin')),xp integer not null default 0,created_at timestamptz default now());
create function ilmora_private.new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,name,nickname) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'name',''),nullif(new.raw_user_meta_data->>'full_name',''),split_part(new.email,'@',1),'Talaba'),80),'Talaba-'||left(new.id::text,6)) on conflict do nothing;return new;end$$;
create trigger ilmora_new_user after insert on auth.users for each row execute function ilmora_private.new_user();
create function public.my_role() returns text language sql stable security definer set search_path='' as $$select coalesce((select role from public.profiles where id=auth.uid()),'guest')$$;
create table public.teacher_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles on delete cascade,name text not null,email text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now());
create table public.documents(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid() references public.profiles on delete cascade,title text not null check(length(title)<=200),body text not null check(length(body)<=100000),updated_at timestamptz default now());
create table public.progress(user_id uuid not null default auth.uid() references public.profiles on delete cascade,lesson_id int not null check(lesson_id between 1 and 40),completed_at timestamptz default now(),primary key(user_id,lesson_id));
create table public.quizzes(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid() references public.profiles on delete cascade,title text not null check(length(title) between 1 and 150),questions jsonb not null check(jsonb_typeof(questions)='array' and jsonb_array_length(questions) between 1 and 100),is_public boolean not null default false,created_at timestamptz default now());
create table public.feedback(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references public.profiles on delete cascade,body text not null check(length(body) between 1 and 3000),created_at timestamptz default now());
create table public.ai_conversations(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid() references public.profiles on delete cascade,title text not null default 'Yangi suhbat',messages jsonb not null default '[]',updated_at timestamptz default now());
create table public.classes(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid() references public.profiles on delete cascade,title text not null check(length(title) between 1 and 120),code text unique not null default upper(left(replace(gen_random_uuid()::text,'-',''),10)),created_at timestamptz default now());
create table public.class_members(class_id uuid references public.classes on delete cascade,user_id uuid references public.profiles on delete cascade,primary key(class_id,user_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),class_id uuid not null references public.classes on delete cascade,owner uuid not null default auth.uid() references public.profiles on delete cascade,title text not null,description text not null,due_at timestamptz,scale integer not null default 100 check(scale in (5,100)),ai_policy text not null default 'guide' check(ai_policy in ('off','guide','full')),created_at timestamptz default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments on delete cascade,student uuid not null default auth.uid() references public.profiles on delete cascade,body text not null check(length(body)<=100000),grade numeric,comment text,created_at timestamptz default now(),unique(assignment_id,student));
create table public.lesson_comments(id uuid primary key default gen_random_uuid(),lesson_id integer not null check(lesson_id between 1 and 40),author uuid not null default auth.uid() references public.profiles on delete cascade,body text not null check(length(body) between 1 and 1500),created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,body text not null,read_at timestamptz,created_at timestamptz default now());
create function public.owns_class(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.classes where id=p_id and owner=auth.uid())$$;
create function public.in_class(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select public.owns_class(p_id) or exists(select 1 from public.class_members where class_id=p_id and user_id=auth.uid())$$;
create function public.owns_assignment(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.assignments where id=p_id and owner=auth.uid())$$;
create function public.can_submit(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.assignments a join public.class_members m on m.class_id=a.class_id where a.id=p_id and m.user_id=auth.uid() and (a.due_at is null or a.due_at>=now()))$$;
-- Default privileges are not trusted; explicitly revoke and grant.
do $$declare t text;begin foreach t in array array['profiles','teacher_requests','documents','progress','quizzes','feedback','ai_conversations','classes','class_members','assignments','submissions','lesson_comments','notifications'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);end loop;end$$;
grant select on public.profiles to authenticated;create policy profiles_self on public.profiles for select to authenticated using(id=auth.uid() or public.my_role()='admin');
grant update(name,nickname) on public.profiles to authenticated;create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
grant select on public.teacher_requests to authenticated;create policy req_read on public.teacher_requests for select to authenticated using(user_id=auth.uid() or public.my_role()='admin');
grant select,insert,update,delete on public.documents,public.quizzes,public.ai_conversations to authenticated;
create policy doc_own on public.documents for all to authenticated using(owner=auth.uid()) with check(owner=auth.uid());
create policy quiz_read on public.quizzes for select to authenticated using(owner=auth.uid() or is_public);create policy quiz_add on public.quizzes for insert to authenticated with check(owner=auth.uid());create policy quiz_edit on public.quizzes for update to authenticated using(owner=auth.uid()) with check(owner=auth.uid());create policy quiz_remove on public.quizzes for delete to authenticated using(owner=auth.uid());
create policy ai_own on public.ai_conversations for all to authenticated using(owner=auth.uid()) with check(owner=auth.uid());
grant select on public.progress to authenticated;create policy progress_own on public.progress for select to authenticated using(user_id=auth.uid());
grant select,insert on public.feedback to authenticated;create policy feedback_add on public.feedback for insert to authenticated with check(user_id=auth.uid());create policy feedback_read on public.feedback for select to authenticated using(user_id=auth.uid() or public.my_role()='admin');
grant select,insert,update,delete on public.classes to authenticated;create policy class_read on public.classes for select to authenticated using(public.in_class(id));create policy class_add on public.classes for insert to authenticated with check(owner=auth.uid() and public.my_role() in ('teacher','admin'));create policy class_edit on public.classes for update to authenticated using(owner=auth.uid()) with check(owner=auth.uid());create policy class_delete on public.classes for delete to authenticated using(owner=auth.uid());
grant select,delete on public.class_members to authenticated;create policy member_read on public.class_members for select to authenticated using(user_id=auth.uid() or public.owns_class(class_id));create policy member_delete on public.class_members for delete to authenticated using(user_id=auth.uid() or public.owns_class(class_id));
grant select,insert,update,delete on public.assignments to authenticated;create policy assignment_read on public.assignments for select to authenticated using(public.in_class(class_id));create policy assignment_add on public.assignments for insert to authenticated with check(owner=auth.uid() and public.owns_class(class_id));create policy assignment_edit on public.assignments for update to authenticated using(owner=auth.uid()) with check(owner=auth.uid() and public.owns_class(class_id));create policy assignment_delete on public.assignments for delete to authenticated using(owner=auth.uid());
grant select,insert on public.submissions to authenticated;create policy sub_read on public.submissions for select to authenticated using(student=auth.uid() or public.owns_assignment(assignment_id));create policy sub_add on public.submissions for insert to authenticated with check(student=auth.uid() and public.can_submit(assignment_id) and grade is null and comment is null);
grant select,insert,delete on public.lesson_comments to authenticated;create policy comments_read on public.lesson_comments for select to authenticated using(true);create policy comments_add on public.lesson_comments for insert to authenticated with check(author=auth.uid());create policy comments_delete on public.lesson_comments for delete to authenticated using(author=auth.uid() or public.my_role()='admin');
grant select,update(read_at) on public.notifications to authenticated;create policy notice_read on public.notifications for select to authenticated using(user_id=auth.uid());create policy notice_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create function public.complete_lesson(p_lesson int) returns int language plpgsql security definer set search_path='' as $$declare added int;begin if auth.uid() is null then raise exception 'Avval kiring';end if;insert into public.progress(user_id,lesson_id) values(auth.uid(),p_lesson) on conflict do nothing;get diagnostics added=row_count;if added=1 then update public.profiles set xp=xp+50 where id=auth.uid();end if;return (select xp from public.profiles where id=auth.uid());end$$;
create function public.leaderboard() returns table(nickname text,xp int) language sql stable security definer set search_path='' as $$select nickname,xp from public.profiles where auth.uid() is not null order by xp desc,id limit 50$$;
create function public.request_teacher() returns void language plpgsql security definer set search_path='' as $$begin if public.my_role()<>'student' then raise exception 'Faqat talaba';end if;insert into public.teacher_requests(user_id,name,email) select p.id,p.name,u.email from public.profiles p join auth.users u on u.id=p.id where p.id=auth.uid() on conflict(user_id) do update set status='pending' where teacher_requests.status='rejected';end$$;
create function public.review_teacher(p_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$declare target uuid;begin if public.my_role()<>'admin' then raise exception 'Ruxsat yo‘q';end if;update public.teacher_requests set status=case when p_approve then 'approved' else 'rejected' end where id=p_id and status='pending' returning user_id into target;if target is null then raise exception 'Ariza topilmadi';end if;if p_approve then update public.profiles set role='teacher' where id=target and role='student';end if;insert into public.notifications(user_id,body) values(target,case when p_approve then 'O‘qituvchilik arizangiz tasdiqlandi.' else 'O‘qituvchilik arizangiz rad etildi.' end);end$$;
create function public.join_class(p_code text) returns uuid language plpgsql security definer set search_path='' as $$declare cid uuid;begin if auth.uid() is null then raise exception 'Avval kiring';end if;select id into cid from public.classes where code=upper(trim(p_code));if cid is null then raise exception 'Guruh kodi topilmadi';end if;insert into public.class_members values(cid,auth.uid()) on conflict do nothing;return cid;end$$;
create function public.add_class_member(p_class uuid,p_email text) returns void language plpgsql security definer set search_path='' as $$declare uid uuid;begin if not public.owns_class(p_class) then raise exception 'Ruxsat yo‘q';end if;select id into uid from auth.users where lower(email)=lower(trim(p_email));if uid is null then raise exception 'Foydalanuvchi topilmadi';end if;insert into public.class_members values(p_class,uid) on conflict do nothing;end$$;
create function public.grade_submission(p_id uuid,p_grade numeric,p_comment text) returns void language plpgsql security definer set search_path='' as $$declare s public.submissions%rowtype;a public.assignments%rowtype;begin select * into s from public.submissions where id=p_id;select * into a from public.assignments where id=s.assignment_id;if a.owner is distinct from auth.uid() or auth.uid() is null then raise exception 'Ruxsat yo‘q';end if;if p_grade<0 or p_grade>a.scale then raise exception 'Baho chegaradan tashqarida';end if;update public.submissions set grade=p_grade,comment=left(p_comment,3000) where id=p_id;insert into public.notifications(user_id,body) values(s.student,'Yozma ishingiz baholandi: '||a.title);end$$;
-- Private, token-authorized live quiz engine. Never expose question keys in a public table.
create table ilmora_private.rooms(id uuid primary key default gen_random_uuid(),host uuid not null references public.profiles on delete cascade,pin text not null unique,title text not null,questions jsonb not null,settings jsonb not null,phase text not null default 'lobby' check(phase in ('lobby','question','reveal','finished')),idx int not null default 0,deadline timestamptz,created_at timestamptz not null default now());
create table ilmora_private.players(id uuid primary key default gen_random_uuid(),room uuid not null references ilmora_private.rooms on delete cascade,token uuid not null unique default gen_random_uuid(),nickname text not null,score int not null default 0,joined_at timestamptz default now());
create table ilmora_private.answers(room uuid references ilmora_private.rooms on delete cascade,player uuid references ilmora_private.players on delete cascade,idx int not null,choice jsonb not null,correct boolean not null,points int not null,primary key(room,player,idx));
create table public.live_signals(id uuid primary key,updated_at timestamptz not null default now());
alter table public.live_signals enable row level security;revoke all on public.live_signals from anon,authenticated;grant select on public.live_signals to anon,authenticated;create policy signals_read on public.live_signals for select to anon,authenticated using(true);
alter publication supabase_realtime add table public.live_signals;
create function ilmora_private.signal(p_room uuid) returns void language sql security definer set search_path='' as $$insert into public.live_signals(id) values(p_room) on conflict(id) do update set updated_at=clock_timestamp()$$;
create function ilmora_private.next_question(p_room uuid) returns void language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;nextidx int;duration int;begin select * into r from ilmora_private.rooms where id=p_room for update;nextidx=case when r.phase='lobby' then 0 else r.idx+1 end;if nextidx>=jsonb_array_length(r.questions) then update ilmora_private.rooms set phase='finished',deadline=null where id=p_room;else duration=greatest(5,least(120,coalesce((r.questions->nextidx->>'time')::int,30)));update ilmora_private.rooms set phase='question',idx=nextidx,deadline=clock_timestamp()+make_interval(secs=>duration) where id=p_room;end if;perform ilmora_private.signal(p_room);end$$;
create function ilmora_private.advance_due(p_room uuid) returns void language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;begin select * into r from ilmora_private.rooms where id=p_room;if r.deadline is null or r.deadline>clock_timestamp() then return;end if;select * into r from ilmora_private.rooms where id=p_room for update;if r.deadline is null or r.deadline>clock_timestamp() then return;end if;if r.phase='question' then update ilmora_private.rooms set phase='reveal',deadline=case when coalesce((r.settings->>'auto')::boolean,false) then clock_timestamp()+interval '7 seconds' else null end where id=p_room;perform ilmora_private.signal(p_room);elsif r.phase='reveal' and coalesce((r.settings->>'auto')::boolean,false) then perform ilmora_private.next_question(p_room);end if;end$$;
create function public.live_create(p_title text,p_questions jsonb,p_settings jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare q jsonb;a jsonb;rid uuid;code text;tries int=0;begin if auth.uid() is null then raise exception 'Avval kiring';end if;if length(trim(p_title)) not between 1 and 150 or jsonb_typeof(p_questions)<>'array' or jsonb_array_length(p_questions) not between 1 and 100 or length(p_questions::text)>200000 then raise exception 'Test hajmi noto‘g‘ri';end if;if (select count(*) from ilmora_private.rooms where host=auth.uid() and phase<>'finished' and created_at>now()-interval '4 hours')>=3 then raise exception 'Bir vaqtda 3 ta faol xona';end if;for q in select value from jsonb_array_elements(p_questions) loop if coalesce(length(q->>'question'),0) not between 1 and 1000 or coalesce(q->>'type','') not in ('choice','boolean','multiple') or jsonb_typeof(q->'options') is distinct from 'array' or jsonb_typeof(q->'answer') is distinct from 'array' then raise exception 'Savol formati noto‘g‘ri';end if;if jsonb_array_length(q->'options') not between 2 and 6 or jsonb_array_length(q->'answer') not between 1 and 6 then raise exception 'Variantlar soni noto‘g‘ri';end if;for a in select value from jsonb_array_elements(q->'answer') loop if jsonb_typeof(a)<>'number' or (a::text)::int<0 or (a::text)::int>=jsonb_array_length(q->'options') then raise exception 'Javob indeksi noto‘g‘ri';end if;end loop;end loop;loop code=lpad(floor(random()*1000000)::int::text,6,'0');begin insert into ilmora_private.rooms(host,pin,title,questions,settings) values(auth.uid(),code,trim(p_title),p_questions,jsonb_build_object('auto',coalesce((p_settings->>'auto')::boolean,false),'late',coalesce((p_settings->>'late')::boolean,false),'projector',coalesce((p_settings->>'projector')::boolean,false),'exam',coalesce((p_settings->>'exam')::boolean,false))) returning id into rid;exit;exception when unique_violation then tries=tries+1;if tries>20 then raise exception 'PIN yaratib bo‘lmadi';end if;end;end loop;perform ilmora_private.signal(rid);return jsonb_build_object('id',rid,'pin',code);end$$;
create function public.live_join(p_pin text,p_name text) returns jsonb language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;p ilmora_private.players%rowtype;begin if length(trim(p_name)) not between 1 and 32 then raise exception 'Ism 1–32 belgi bo‘lsin';end if;select * into r from ilmora_private.rooms where pin=trim(p_pin) and created_at>now()-interval '4 hours' for update;if not found or r.phase='finished' then raise exception 'Xona topilmadi yoki tugagan';end if;if r.phase<>'lobby' and not coalesce((r.settings->>'late')::boolean,false) then raise exception 'O‘yin boshlangan';end if;if (select count(*) from ilmora_private.players where room=r.id)>=50 then raise exception 'Xona to‘lgan';end if;if exists(select 1 from ilmora_private.players where room=r.id and lower(nickname)=lower(trim(p_name))) then raise exception 'Bu ism band';end if;insert into ilmora_private.players(room,nickname) values(r.id,trim(p_name)) returning * into p;perform ilmora_private.signal(r.id);return jsonb_build_object('id',r.id,'token',p.token,'pin',r.pin);end$$;
create function public.live_state(p_room uuid,p_token uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;p ilmora_private.players%rowtype;host boolean;q jsonb;mine jsonb;rankings jsonb;stats jsonb;begin select * into r from ilmora_private.rooms where id=p_room;if not found then raise exception 'Xona topilmadi';end if;host=auth.uid() is not null and auth.uid()=r.host;if not host then select * into p from ilmora_private.players where room=p_room and token=p_token;if not found then raise exception 'Ruxsat yo‘q';end if;end if;perform ilmora_private.advance_due(p_room);select * into r from ilmora_private.rooms where id=p_room;q=r.questions->r.idx;if r.phase in ('question','reveal') then if not host and r.phase='question' and (r.settings->>'projector')::boolean then q=jsonb_build_object('options',(select jsonb_agg('Variant '||(ord::text) order by ord) from jsonb_array_elements(q->'options') with ordinality as o(v,ord)),'type',q->>'type','time',q->'time');elsif r.phase='question' then q=jsonb_build_object('question',q->'question','options',q->'options','type',q->'type','time',q->'time','mediaType',q->'mediaType','mediaUrl',q->'mediaUrl');end if;else q=null;end if;select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',nickname,'score',score) order by score desc,joined_at),'[]') into rankings from ilmora_private.players where room=p_room;if not host then select jsonb_build_object('submitted',true,'choice',choice,'correct',case when r.phase<>'question' then correct else null end,'points',case when r.phase<>'question' then points else null end) into mine from ilmora_private.answers where room=p_room and player=p.id and idx=r.idx;end if;if r.phase='reveal' then select coalesce(jsonb_agg(jsonb_build_object('choice',choice,'count',cnt)),'[]') into stats from (select choice,count(*) cnt from ilmora_private.answers where room=p_room and idx=r.idx group by choice)s;end if;return jsonb_build_object('id',r.id,'pin',r.pin,'title',r.title,'phase',r.phase,'index',r.idx,'total',jsonb_array_length(r.questions),'question',q,'deadline',r.deadline,'serverTime',clock_timestamp(),'players',case when r.phase='question' and not host then '[]'::jsonb else rankings end,'count',jsonb_array_length(rankings),'answered',(select count(*) from ilmora_private.answers where room=p_room and idx=r.idx),'mine',mine,'stats',stats,'host',host,'settings',r.settings);end$$;
create function public.live_control(p_room uuid,p_action text,p_player uuid default null) returns void language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;begin select * into r from ilmora_private.rooms where id=p_room and host=auth.uid() for update;if not found then raise exception 'Ruxsat yo‘q';end if;if p_action='start' and r.phase='lobby' or p_action='next' and r.phase='reveal' then perform ilmora_private.next_question(p_room);elsif p_action='reveal' and r.phase='question' then update ilmora_private.rooms set phase='reveal',deadline=case when (settings->>'auto')::boolean then clock_timestamp()+interval '7 seconds' else null end where id=p_room;elsif p_action='finish' and r.phase<>'finished' then update ilmora_private.rooms set phase='finished',deadline=null where id=p_room;elsif p_action='kick' and r.phase='lobby' then delete from ilmora_private.players where id=p_player and room=p_room;else raise exception 'Bu amal hozir mumkin emas';end if;perform ilmora_private.signal(p_room);end$$;
create function public.live_answer(p_room uuid,p_token uuid,p_choice jsonb,p_index int) returns void language plpgsql security definer set search_path='' as $$declare r ilmora_private.rooms%rowtype;p ilmora_private.players%rowtype;q jsonb;good boolean;points int;remaining numeric;secs int;changed int;begin select * into r from ilmora_private.rooms where id=p_room for share;if not found or r.phase<>'question' or r.idx<>p_index or r.deadline<=clock_timestamp() then raise exception 'Savol vaqti tugagan';end if;select * into p from ilmora_private.players where room=p_room and token=p_token;if not found then raise exception 'Ruxsat yo‘q';end if;q=r.questions->r.idx;if jsonb_typeof(p_choice) is distinct from 'array' or jsonb_array_length(p_choice) not between 1 and 6 then raise exception 'Javob noto‘g‘ri';end if;if exists(select 1 from jsonb_array_elements(p_choice) a where jsonb_typeof(a)<>'number' or (a::text)::int<0 or (a::text)::int>=jsonb_array_length(q->'options')) then raise exception 'Variant noto‘g‘ri';end if;good=(p_choice @> (q->'answer') and p_choice <@ (q->'answer') and jsonb_array_length(p_choice)=jsonb_array_length(q->'answer'));secs=greatest(5,least(120,coalesce((q->>'time')::int,30)));remaining=greatest(0,least(1,extract(epoch from r.deadline-clock_timestamp())/secs));points=case when not good then 0 when (r.settings->>'exam')::boolean then 1000 else 500+round(500*remaining)::int end;insert into ilmora_private.answers values(p_room,p.id,r.idx,p_choice,good,points) on conflict do nothing;get diagnostics changed=row_count;if changed=0 then raise exception 'Javob allaqachon yuborilgan';end if;update ilmora_private.players set score=score+points where id=p.id;-- No broadcast per answer; poll to avoid message bursts.
end$$;
create function public.live_reports() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'title',r.title,'pin',r.pin,'phase',r.phase,'date',r.created_at,'count',(select count(*) from ilmora_private.players p where p.room=r.id)) order by r.created_at desc),'[]') from ilmora_private.rooms r where r.host=auth.uid()$$;
-- AI quotas: server-only, transaction serialized per day. Set limits BELOW actual free tier.
create table ilmora_private.ai_usage(day date not null,role text not null,user_id uuid not null,used int not null default 0,primary key(day,user_id));
create function public.ai_reserve(p_user uuid,p_limit int) returns boolean language plpgsql security definer set search_path='' as $$declare role_name text;d date=(now() at time zone 'UTC')::date;all_used int;role_used int;user_used int;role_limit int;begin if p_limit<1 or p_limit>10000 then return false;end if;select role into role_name from public.profiles where id=p_user;if role_name is null then return false;end if;perform pg_advisory_xact_lock(81231);select coalesce(sum(used),0) into all_used from ilmora_private.ai_usage where day=d;select coalesce(sum(used),0) into role_used from ilmora_private.ai_usage where day=d and role=role_name;select coalesce(sum(used),0) into user_used from ilmora_private.ai_usage where day=d and user_id=p_user;role_limit=case role_name when 'teacher' then greatest(1,floor(p_limit*.6)::int) when 'student' then floor(p_limit*.3)::int else greatest(1,floor(p_limit*.1)::int) end;if all_used>=p_limit or role_used>=role_limit or user_used>=case when role_name='student' then 3 else 12 end then return false;end if;insert into ilmora_private.ai_usage(day,role,user_id,used) values(d,role_name,p_user,1) on conflict(day,user_id) do update set used=ai_usage.used+1;return true;end$$;
-- Expose only deliberate RPCs. No PUBLIC execute on private helpers.
revoke execute on all functions in schema ilmora_private from public,anon,authenticated;
revoke execute on function public.my_role(),public.owns_class(uuid),public.in_class(uuid),public.owns_assignment(uuid),public.can_submit(uuid),public.complete_lesson(int),public.leaderboard(),public.request_teacher(),public.review_teacher(uuid,boolean),public.join_class(text),public.add_class_member(uuid,text),public.grade_submission(uuid,numeric,text),public.live_create(text,jsonb,jsonb),public.live_join(text,text),public.live_state(uuid,uuid),public.live_control(uuid,text,uuid),public.live_answer(uuid,uuid,jsonb,int),public.live_reports(),public.ai_reserve(uuid,int) from public,anon,authenticated;
grant execute on function public.my_role(),public.owns_class(uuid),public.in_class(uuid),public.owns_assignment(uuid),public.can_submit(uuid),public.complete_lesson(int),public.leaderboard(),public.request_teacher(),public.review_teacher(uuid,boolean),public.join_class(text),public.add_class_member(uuid,text),public.grade_submission(uuid,numeric,text),public.live_create(text,jsonb,jsonb),public.live_control(uuid,text,uuid),public.live_reports() to authenticated;
grant execute on function public.live_join(text,text),public.live_state(uuid,uuid),public.live_answer(uuid,uuid,jsonb,int) to anon,authenticated;
grant execute on function public.ai_reserve(uuid,int) to service_role;
commit;
